-- Generated localized release notes.
local _, namespace = ...
namespace.releaseNotesByLocale = {["deDE"]={["sections"]={{["items"]={"Füge über das QuestTogether-Menü eines Spielers eine private Notiz hinzu, bearbeite oder lösche sie. Die Notiz erscheint, wenn du mit der Maus über den Spieler fährst.","Notizen sind für alle deine Charaktere verfügbar und bleiben auf deinem Computer. Sie werden niemals an andere Spieler gesendet oder in Diagnosedaten aufgenommen."},["title"]="Private Spielernotizen"},{["items"]={"Klappe einzelne Spielerspalten ein, um Platz zu schaffen, und wieder aus, wenn du die Details brauchst.","Mit der Schaltfläche „Tastatur“ kannst du per Pfeiltasten durch Quests navigieren, mit der Eingabetaste Ziele ausklappen und mit der Leertaste Questaktionen öffnen. Escape kehrt zur normalen Steuerung zurück.","Abgeschlossene Quests werden jetzt von fehlenden Quests unterschieden, wenn das aktualisierte Addon des anderen Spielers dessen Questverlauf bestätigen kann. Ist der Verlauf unbekannt, bleibt die Kennzeichnung „Nicht im Questlog“.","Verständlichere Erklärungen beim Teilen von Quests zeigen, warum eine Anfrage nicht fortgesetzt werden konnte. Spielertooltips zeigen außerdem kürzlich von WoW gemeldete Ergebnisse des Teilens."},["title"]="Verbesserungen am Gruppenquestlog"},{["items"]={"Viele Tipps im Chat enthalten jetzt anklickbare Verknüpfungen zum passenden Fenster oder zur passenden Einstellung.","Wenn du mit der Maus über einen weit entfernten Spieler fährst, werden jetzt aktuelle Spielerdaten und die vollständige Mitgliederliste seiner Gruppe mit bis zu fünf Spielern angefordert. Solange du darüber verweilst, wird die Anfrage bei Bedarf wiederholt."},["tip"]={["label"]="Tipp:",["text"]="Gib /qt tip oder /qt hint ein, um einen Tipp anzuzeigen, und erkunde QuestTogether über dessen anklickbare Verknüpfungen."},["title"]="Tipps und Spielertooltips"}},["version"]="7.2.0",["welcome"]="Private Spielernotizen und ein nützlicheres Gruppenquestlog."},["esES"]={["sections"]={{["items"]={"Añade, edita o elimina una nota privada desde el menú de QuestTogether de un jugador. Las notas aparecen al pasar el cursor sobre ese jugador.","Las notas se comparten entre tus personajes y permanecen en tu ordenador. Nunca se envían a otros jugadores ni se incluyen en los diagnósticos."},["title"]="Notas privadas sobre jugadores"},{["items"]={"Contrae las columnas de jugadores individualmente para ganar espacio y vuelve a expandirlas cuando necesites ver los detalles.","Usa el botón Teclado para recorrer las misiones con las flechas, expandir los objetivos con Intro y abrir las acciones de misión con Espacio. Escape vuelve a los controles habituales.","Las misiones completadas ahora se distinguen de las que faltan cuando el addon actualizado del otro jugador puede confirmar su historial de misiones. Si el historial es desconocido, se siguen indicando como ausentes del registro de misiones.","Las explicaciones más claras al compartir misiones te ayudan a entender por qué no pudo continuar una solicitud. Las descripciones emergentes de los jugadores también muestran los resultados recientes de compartir misiones comunicados por WoW."},["title"]="Mejoras del registro de misiones del grupo"},{["items"]={"Muchos consejos del chat ahora incluyen enlaces a la ventana o al ajuste correspondiente.","Al pasar el cursor sobre un jugador lejano, ahora se solicitan sus datos actualizados y la lista completa de integrantes de su grupo de hasta cinco jugadores. La solicitud se reintenta mientras mantengas el cursor sobre él."},["tip"]={["label"]="Consejo:",["text"]="Escribe /qt tip o /qt hint para ver un consejo y usa sus enlaces para explorar QuestTogether."},["title"]="Consejos y descripciones emergentes de jugadores"}},["version"]="7.2.0",["welcome"]="Notas privadas sobre jugadores y un registro de misiones del grupo más útil."},["esMX"]={["sections"]={{["items"]={"Agrega, edita o elimina una nota privada desde el menú de QuestTogether de un jugador. Las notas aparecen al pasar el cursor sobre ese jugador.","Las notas se comparten entre tus personajes y permanecen en tu computadora. Nunca se envían a otros jugadores ni se incluyen en los diagnósticos."},["title"]="Notas privadas sobre jugadores"},{["items"]={"Contrae las columnas de jugadores individualmente para ganar espacio y vuelve a expandirlas cuando necesites ver los detalles.","Usa el botón Teclado para recorrer las misiones con las flechas, expandir los objetivos con Intro y abrir las acciones de misión con Espacio. Escape vuelve a los controles habituales.","Las misiones completadas ahora se distinguen de las que faltan cuando el addon actualizado del otro jugador puede confirmar su historial de misiones. Si el historial es desconocido, se siguen indicando como ausentes del registro de misiones.","Las explicaciones más claras al compartir misiones te ayudan a entender por qué no pudo continuar una solicitud. Las descripciones emergentes de los jugadores también muestran los resultados recientes de compartir misiones comunicados por WoW."},["title"]="Mejoras del registro de misiones del grupo"},{["items"]={"Muchos consejos del chat ahora incluyen enlaces a la ventana o al ajuste correspondiente.","Al pasar el cursor sobre un jugador lejano, ahora se solicitan sus datos actualizados y la lista completa de integrantes de su grupo de hasta cinco jugadores. La solicitud se reintenta mientras mantengas el cursor sobre él."},["tip"]={["label"]="Consejo:",["text"]="Escribe /qt tip o /qt hint para ver un consejo y usa sus enlaces para explorar QuestTogether."},["title"]="Consejos y descripciones emergentes de jugadores"}},["version"]="7.2.0",["welcome"]="Notas privadas sobre jugadores y un registro de misiones del grupo más útil."},["frFR"]={["sections"]={{["items"]={"Ajoutez, modifiez ou supprimez une note privée depuis le menu QuestTogether d’un joueur. Elle apparaît lorsque vous survolez ce joueur.","Les notes sont communes à vos personnages et restent sur votre ordinateur. Elles ne sont jamais envoyées aux autres joueurs ni incluses dans les diagnostics."},["title"]="Notes privées sur les joueurs"},{["items"]={"Réduisez les colonnes des joueurs individuellement pour gagner de la place, puis développez-les lorsque vous avez besoin des détails.","Utilisez le bouton Clavier pour parcourir les quêtes avec les flèches, développer les objectifs avec Entrée et ouvrir les actions de quête avec Espace. Échap rétablit les commandes habituelles.","Les quêtes terminées sont désormais distinguées des quêtes manquantes lorsque l’addon à jour de l’autre joueur peut confirmer son historique de quêtes. Si cet historique est inconnu, la quête reste indiquée comme absente du journal.","Des explications plus claires sur le partage de quêtes vous aident à comprendre pourquoi une demande n’a pas pu aboutir. Les infobulles des joueurs affichent aussi les résultats de partage récents signalés par WoW."},["title"]="Améliorations du journal de quêtes du groupe"},{["items"]={"De nombreuses astuces du chat proposent désormais des raccourcis cliquables vers la fenêtre ou le réglage correspondant.","Survoler un joueur éloigné demande désormais ses informations à jour et la liste complète des membres de son groupe de cinq joueurs maximum. Les demandes sont réessayées tant que vous maintenez le survol."},["tip"]={["label"]="Astuce :",["text"]="Saisissez /qt tip ou /qt hint pour afficher une astuce, puis utilisez ses raccourcis cliquables pour découvrir QuestTogether."},["title"]="Astuces et infobulles des joueurs"}},["version"]="7.2.0",["welcome"]="Des notes privées sur les joueurs et un journal de quêtes du groupe plus pratique."},["itIT"]={["sections"]={{["items"]={"Aggiungi, modifica o elimina una nota privata dal menu QuestTogether di un giocatore. La nota compare quando passi il cursore su quel giocatore.","Le note sono condivise tra i tuoi personaggi e restano sul tuo computer. Non vengono mai inviate ad altri giocatori né incluse nei dati diagnostici."},["title"]="Note private sui giocatori"},{["items"]={"Comprimi le singole colonne dei giocatori per fare spazio ed espandile quando ti servono i dettagli.","Usa il pulsante Tastiera per scegliere le missioni con le frecce, espandere gli obiettivi con Invio e aprire le azioni della missione con la barra spaziatrice. Esc ripristina i comandi normali.","Le missioni completate vengono ora distinte da quelle mancanti quando l’addon aggiornato dell’altro giocatore può confermarne la cronologia. Se la cronologia è sconosciuta, resta l’indicazione «Non nel registro».","Spiegazioni più chiare sulla condivisione delle missioni aiutano a capire perché una richiesta non è potuta proseguire. Le descrizioni dei giocatori mostrano anche i risultati recenti della condivisione comunicati da WoW."},["title"]="Miglioramenti al registro missioni del gruppo"},{["items"]={"Molti consigli in chat ora includono collegamenti cliccabili alla finestra o all’impostazione pertinente.","Passare il cursore su un giocatore lontano ora richiede informazioni aggiornate e l’elenco completo del suo gruppo normale. I tentativi proseguono finché il cursore resta sul giocatore."},["tip"]={["label"]="Consiglio:",["text"]="Digita /qt tip o /qt hint per vedere un consiglio, poi usa i suoi collegamenti cliccabili per esplorare QuestTogether."},["title"]="Consigli e descrizioni dei giocatori"}},["version"]="7.2.0",["welcome"]="Note private sui giocatori e un registro missioni del gruppo più utile."},["koKR"]={["sections"]={{["items"]={"플레이어의 QuestTogether 메뉴에서 비공개 메모를 추가, 수정 또는 삭제할 수 있습니다. 해당 플레이어에게 마우스를 올리면 메모가 표시됩니다.","메모는 내 캐릭터 간에 공유되며 내 컴퓨터에만 저장됩니다. 다른 플레이어에게 전송되거나 진단 데이터에 포함되지 않습니다."},["title"]="플레이어별 비공개 메모"},{["items"]={"플레이어별 열을 접어 공간을 확보하고, 자세한 정보가 필요할 때 다시 펼칠 수 있습니다.","키보드 버튼을 누르면 방향키로 퀘스트를 선택하고, Enter로 목표를 펼치고, Space로 퀘스트 작업 메뉴를 열 수 있습니다. Escape를 누르면 일반 조작으로 돌아갑니다.","다른 플레이어의 업데이트된 애드온에서 퀘스트 이력을 확인할 수 있으면 완료한 퀘스트와 없는 퀘스트를 구분합니다. 이력을 알 수 없으면 계속 \"목록에 없음\"으로 표시합니다.","퀘스트 공유 요청을 진행할 수 없는 이유를 더 명확하게 안내합니다. 플레이어 툴팁에는 WoW에서 알려 준 최근 공유 결과도 표시됩니다."},["title"]="파티 퀘스트 목록 개선"},{["items"]={"많은 채팅 도움말에 관련 창이나 설정을 여는 클릭 가능한 바로가기가 추가되었습니다.","멀리 있는 플레이어에게 마우스를 올리면 최신 정보와 일반 파티의 전체 명단을 요청합니다. 마우스를 올려 둔 동안 필요한 경우 다시 시도합니다."},["tip"]={["label"]="도움말:",["text"]="/qt tip 또는 /qt hint를 입력해 도움말을 확인하고, 클릭 가능한 바로가기로 QuestTogether의 기능을 살펴보세요."},["title"]="도움말과 플레이어 툴팁"}},["version"]="7.2.0",["welcome"]="플레이어별 비공개 메모와 더욱 유용해진 파티 퀘스트 목록을 만나보세요."},["ptBR"]={["sections"]={{["items"]={"Adicione, edite ou exclua uma nota privada pelo menu do QuestTogether de um jogador. As notas aparecem quando você passa o cursor sobre esse jogador.","As notas são compartilhadas entre seus personagens e ficam no seu computador. Elas nunca são enviadas a outros jogadores nem incluídas nos diagnósticos."},["title"]="Notas privadas sobre jogadores"},{["items"]={"Recolha as colunas dos jogadores individualmente para ganhar espaço e expanda-as novamente quando precisar dos detalhes.","Use o botão Teclado para navegar pelas missões com as setas, expandir objetivos com Enter e abrir ações da missão com Espaço. Escape retorna aos controles normais.","As missões concluídas agora são diferenciadas das missões ausentes quando o addon atualizado do outro jogador consegue confirmar o histórico de missões dele. Se o histórico for desconhecido, elas continuam indicadas como fora do registro de missões.","Explicações mais claras sobre o compartilhamento de missões ajudam a entender por que uma solicitação não pôde prosseguir. As dicas dos jogadores também mostram resultados recentes de compartilhamento informados pelo WoW."},["title"]="Melhorias no registro de missões do grupo"},{["items"]={"Muitas dicas do chat agora incluem atalhos clicáveis para a janela ou configuração correspondente.","Ao passar o cursor sobre um jogador distante, agora são solicitados dados atualizados e a lista completa de integrantes do grupo dele, de até cinco jogadores. Novas tentativas são feitas enquanto você mantiver o cursor sobre ele."},["tip"]={["label"]="Dica:",["text"]="Digite /qt tip ou /qt hint para ver uma dica e use os atalhos clicáveis dela para explorar o QuestTogether."},["title"]="Dicas e informações de jogadores"}},["version"]="7.2.0",["welcome"]="Notas privadas sobre jogadores e um registro de missões do grupo mais útil."},["ruRU"]={["sections"]={{["items"]={"Добавляйте, редактируйте и удаляйте личные заметки через меню игрока в QuestTogether. Заметка появляется при наведении указателя на этого игрока.","Заметки доступны всем вашим персонажам и хранятся только на вашем компьютере. Они никогда не отправляются другим игрокам и не включаются в диагностические данные."},["title"]="Личные заметки об игроках"},{["items"]={"Сворачивайте отдельные столбцы игроков, чтобы освободить место, и разворачивайте их, когда нужны подробности.","Нажмите кнопку «Клавиатура», чтобы выбирать задания стрелками, раскрывать цели клавишей Enter и открывать действия с заданием клавишей пробела. Escape возвращает обычное управление.","Выполненные задания теперь отличаются от отсутствующих, если обновлённый аддон другого игрока может подтвердить его историю заданий. При неизвестной истории сохраняется пометка «Нет в журнале».","Более понятные пояснения при передаче заданий помогают узнать, почему запрос не удалось выполнить. Подсказки игроков также показывают недавние результаты передачи, полученные от WoW."},["title"]="Улучшения журнала заданий группы"},{["items"]={"Многие советы в чате теперь содержат ссылки для перехода к нужному окну или настройке.","При наведении на далёкого игрока теперь запрашиваются свежие сведения и полный состав его обычной группы. Пока указатель остаётся на игроке, запросы при необходимости повторяются."},["tip"]={["label"]="Совет:",["text"]="Введите /qt tip или /qt hint, чтобы увидеть совет, и воспользуйтесь его ссылками для знакомства с QuestTogether."},["title"]="Советы и подсказки игроков"}},["version"]="7.2.0",["welcome"]="Личные заметки об игроках и более удобный журнал заданий группы."},["zhCN"]={["sections"]={{["items"]={"在玩家的 QuestTogether 菜单中添加、编辑或删除私人备注。将鼠标悬停在该玩家上时即可查看备注。","备注在你的角色之间共享，仅保存在你的电脑上，绝不会发送给其他玩家，也不会包含在诊断数据中。"},["title"]="私人玩家备注"},{["items"]={"可折叠单个玩家的列以腾出空间，需要查看详细信息时再展开。","点击“键盘”按钮后，可用方向键选择任务、Enter 展开目标、空格键打开任务操作菜单。按 Escape 恢复正常操作。","当其他玩家更新后的插件能够确认其任务历史时，已完成的任务现在会与缺少的任务区分显示。无法确认历史时，仍显示为“不在任务日志中”。","更清晰的任务共享说明可帮助你了解请求无法继续的原因。玩家提示中也会显示 WoW 报告的近期共享结果。"},["title"]="队伍任务日志改进"},{["items"]={"许多聊天小提示现在包含可点击的快捷链接，可直接打开相关窗口或设置。","将鼠标悬停在远处的玩家上时，现在会请求最新信息和完整的小队成员名单，并在持续悬停期间按需重试。"},["tip"]={["label"]="提示：",["text"]="输入 /qt tip 或 /qt hint 查看一条小提示，再点击其中的快捷链接探索 QuestTogether。"},["title"]="小提示与玩家提示信息"}},["version"]="7.2.0",["welcome"]="新增私人玩家备注，让队伍任务日志更加实用。"},["zhTW"]={["sections"]={{["items"]={"在玩家的 QuestTogether 選單中新增、編輯或刪除私人備註。將滑鼠游標移至該玩家上方時即可查看備註。","備註會在你的角色之間共用，僅儲存在你的電腦上，絕不會傳送給其他玩家，也不會包含在診斷資料中。"},["title"]="私人玩家備註"},{["items"]={"可收合個別玩家的欄位以騰出空間，需要查看詳細資訊時再展開。","點擊「鍵盤」按鈕後，可用方向鍵選擇任務、Enter 展開目標、空白鍵開啟任務操作選單。按 Escape 恢復一般操作。","當其他玩家更新後的插件能確認其任務紀錄時，已完成的任務現在會與缺少的任務區分顯示。無法確認紀錄時，仍顯示為「不在任務日誌中」。","更清楚的任務分享說明可幫助你了解請求無法繼續的原因。玩家提示中也會顯示 WoW 回報的近期分享結果。"},["title"]="隊伍任務日誌改進"},{["items"]={"許多聊天小提示現在包含可點擊的捷徑，可直接開啟相關視窗或設定。","將滑鼠游標移至遠處的玩家上方時，現在會請求最新資訊和完整的小隊成員名單，並在持續停留期間視需要重試。"},["tip"]={["label"]="提示：",["text"]="輸入 /qt tip 或 /qt hint 查看一則小提示，再點擊其中的捷徑探索 QuestTogether。"},["title"]="小提示與玩家提示資訊"}},["version"]="7.2.0",["welcome"]="新增私人玩家備註，讓隊伍任務日誌更加實用。"}}
